<script setup lang="ts">
const wizard = useSubmissionWizard();
const title = computed(() => wizard.payload.category ? `ثبت آگهی در ${wizard.payload.category.title}` : "ثبت آگهی جدید");
useHead({ title: () => `${title.value} | هفت‌سو`, meta: [{ name: "robots", content: "noindex,nofollow" }] });
</script>
<template><main class="submission-page"><header class="submission-head"><div><span class="eyebrow">ویزارد ثبت آگهی</span><h1>{{ title }}</h1></div><span class="save-indicator" :data-state="wizard.saveState.value">{{ wizard.saveState.value === 'saving' ? 'در حال ذخیره…' : wizard.saveState.value === 'offline' ? 'ذخیره محلی' : 'ذخیره شد' }}</span></header><SubmissionStepper :current="wizard.step.value" :current-index="wizard.currentIndex.value" @select="wizard.goTo"/><div v-if="wizard.submittedPostId.value" class="submission-success" role="status"><span>✓</span><h2>آگهی با موفقیت ثبت شد</h2><p>شناسه پیگیری: <b dir="ltr">{{ wizard.submittedPostId.value }}</b></p><NuxtLink class="primary-action" to="/my/posts">مشاهده آگهی‌های من</NuxtLink></div><section v-else class="submission-card"><CategoryWizard v-if="wizard.step.value === 'category'" v-model="wizard.payload.category"/><DynamicSubmissionForm v-else-if="wizard.step.value === 'details'" :category-slug="wizard.payload.category?.slug" :model-value="wizard.payload.fields" :error="wizard.errors.value.title" @update:model-value="wizard.payload.fields = $event"/><div v-else-if="wizard.step.value === 'location'"><h2>موقعیت و محله آگهی</h2><p class="submission-hint">برای حفظ حریم خصوصی، موقعیت دقیق به‌صورت پیش‌فرض پنهان است.</p><GeoSelector tenant-id="00000000-0000-4000-8000-000000000001" :model-value="wizard.payload.location" @update:model-value="wizard.payload.location = $event"/><small v-if="wizard.errors.value.location" class="field-error">{{ wizard.errors.value.location }}</small></div><MediaDescriptionStep v-else-if="wizard.step.value === 'media'" :media="wizard.payload.media" :description="wizard.payload.description" :error="wizard.errors.value.description" @update:media="wizard.payload.media = $event" @update:description="wizard.payload.description = $event"/><ContactPrivacyStep v-else-if="wizard.step.value === 'contact'" :payload="wizard.payload" :errors="wizard.errors.value"/><SubmissionPreview v-else :payload="wizard.payload"/><footer class="submission-actions"><button v-if="wizard.currentIndex.value > 0" class="secondary-action" type="button" @click="wizard.previous">مرحله قبل</button><span></span><button v-if="wizard.step.value !== 'preview'" class="primary-action" type="button" @click="wizard.next">ادامه</button><button v-else class="primary-action" type="button" @click="wizard.submit">ثبت نهایی آگهی</button></footer></section></main></template>
